    /// Seal a compiled playbook for a seat, replacing whatever it had sealed.
    ///
    /// What a host calls at the end of a Lull, once the verifier has accepted
    /// the submission: the latest verified submission replaces the previous
    /// one, any number of times, until the timer ends (item 5). Sealing resets
    /// that seat's execution state — the route starts from the top, every
    /// handler's cooldown and fire count go back to zero — and keeps the
    /// match-long commander death count, because sealing a playbook does not
    /// un-kill a commander.
    ///
    /// `false` when `seat` is not a seat of this match.
    pub fn seal_playbook(&mut self, seat: SeatId, plan: Plan) -> bool {
        let index = usize::from(seat.raw());
        if index >= self.interpreter.len() {
            return false;
        }
        // E7: rule: an event's value is derived output, never hashed, and saturates
        let steps = i64::try_from(plan.route().len()).unwrap_or(i64::MAX);
        let hp = self.commander_hp_of(seat);
        self.interpreter.seal(index, plan, hp);
        let tick = self.tick;
        self.emit(
            tick,
            Emission::of(EventKind::PlanSealed).seat(seat).value(steps),
        );
        true
    }

    /// The hit points of a seat's commander, or zero when it has none.
    fn commander_hp_of(&self, seat: SeatId) -> i32 {
        self.commander_of(seat)
            .and_then(|commander| self.units.row_of(commander).ok())
            .and_then(|row| self.units.hit_points().get(row.index()).copied())
            // E7: rule: a seat with no commander row has no hit points
            .map_or(0, Hp::raw)
    }

    /// Send a unit somewhere: write its destination and ask for a route.
    ///
    /// Crate-internal, and the interpreter is its only caller. The walking
    /// itself is T7's — one legal step at a time, one-voxel climbs, blocked by
    /// walls, craters and trenches — and none of it changes because a playbook
    /// rather than the harness chose the destination.
    pub(crate) fn set_unit_destination(&mut self, unit: u32, to: [Fx; 3]) {
        let index = crate::math::index::row(unit);
        // **A destination that has not changed is not a new order.** Clearing
        // the route and asking for another one is what a *change* of mind
        // costs; doing it for an unchanged destination throws away the route
        // the unit is walking, every tick, so the repath queue re-plans it and
        // the unit never takes a step. A program that says "go home" on every
        // tick of the walk home — which is exactly what the built-in programs
        // do, because they are stateless — would otherwise stand still for
        // ever.
        if self.units.destinations().get(index).copied() == Some(to) {
            return;
        }
        if let Some(slot) = self.units.destinations_mut().get_mut(index) {
            *slot = to;
        }
        self.router.clear(unit);
        self.router.request(unit);
    }

    /// Deploy a beacon for `seat` at `at`, carrying `mandate`.
    ///
    /// `None` when the seat has used its share of [`BEACON_TABLE_ROOM`], which
    /// the caller reports as a step failure rather than growing a column inside
    /// a tick.
    ///
    /// The `$` is **not** charged here, because it was charged already: spec
    /// section 7 has it leave the treasury "the moment an order commits:
    /// deploy starts", twelve seconds before this call, and the interpreter
    /// charges it then ([`World::charge_deploy`]) and refunds it on an abort
    /// ([`World::refund_deploy`]). Placing the beacon is where the paid-for
    /// asset appears, not where it is paid for (register X-12, item 124 (5)
    /// (f), fixed in S1 by item 126 (2) (f)).
    ///
    /// # Errors
    ///
    /// [`PlaceRefused`]: a seat this world has not got, a share or a table
    /// with no room, or a placement counter with no next value.
    pub(crate) fn place_beacon(
        &mut self,
        seat: SeatId,
        at: [Fx; 3],
        mandate: MandateKind,
    ) -> Result<BeaconId, PlaceRefused> {
        let index = self.seat_row(seat).ok_or(PlaceRefused::NoSuchSeat)?;
        // The seat's own share of the world total (item 127 (12)): the rows it
        // holds less its core, which the generator placed and no deploy paid
        // for. Since S2 the rows it holds are its live beacons (E1), so a
        // beacon that died and settled gives its place in the share back.
        let placed = self.beacons.count_of(seat).saturating_sub(1);
        if placed >= room_per_seat(BEACON_TABLE_ROOM, self.seats.len()) {
            return Err(PlaceRefused::ShareFull);
        }
        // The table's room is checked before the ordinal is taken, so a refused
        // deploy spends no name.
        self.beacons
            .vacancy(self.beacon_limit)
            .map_err(|_| PlaceRefused::TableFull)?;
        let ordinal = self
            .seats
            .take_ordinal(index)
            .ok_or(PlaceRefused::CounterSpent)?;
        // Read typed at load (`structures.beacon`), so a placed beacon always
        // has its hit points.
        let hp = self.rules.beacon_row().hp;
        let placed = self
            .beacons
            .place(
                self.beacon_limit,
                seat,
                at,
                BeaconMandate {
                    kind: mandate,
                    program_id: ProgramId::NONE,
                },
                BeaconStart {
                    hp,
                    dormant: false,
                    ordinal,
                    // A placed beacon carries no weapon; only a core fires.
                    ready_at: 0,
                },
            )
            .map_err(|_| PlaceRefused::TableFull)?;
        let row = placed.id.row().map_err(|_| PlaceRefused::NoRow)?;
        match self.beacon_alive.get_mut(row.index()) {
            Some(slot) => *slot = hp.is_alive(),
            None => self.beacon_alive.push(hp.is_alive()),
        }
        Ok(placed.id)
    }

    /// Write a beacon's writ. The interpreter's committed `set_mandate` row.
    ///
    /// Item 20: switching a beacon's mandate **clears the old mandate's
    /// settings and targets**, and the Quartermaster priority belongs to the
    /// beacon rather than the mandate, so it survives. Both halves are one
    /// write here, in the one place a writ changes, so neither can be forgotten
    /// by a second caller.
    pub(crate) fn set_beacon_mandate(&mut self, row: usize, mandate: MandateKind) {
        let id = self.beacons.ids().get(row).copied();
        if let Some(slot) = self.beacons.mandates_mut().get_mut(row) {
            *slot = mandate.id();
        }
        if let Some(slot) = self.beacons.scout_counts_mut().get_mut(row) {
            *slot = 0;
        }
        // The Mine settings are the old mandate's settings too, and the seam
        // the beacon held was chosen under them: both go (`crate::mining`).
        self.beacons
            .set_mine_settings(row, crate::mining::MineSettings::default());
        if let Some(slot) = self.beacons.seams_mut().get_mut(row) {
            *slot = NO_FEATURE;
        }
        // The Common settings are the old mandate's settings too (spec
        // section 5: switching clears the old settings); the switch's own row
        // writes the new ones after this.
        if let Some(slot) = self.beacons.commons_mut().get_mut(row) {
            *slot = crate::tables::Common::DEFAULT;
        }
        // So are the Build settings (S2's `site`), and the work paid for in
        // advance and not yet done goes back to the treasury: it was paid for
        // the old writ's drones (`World::return_site_funds`).
        self.set_build_settings(row, crate::site::BuildSettings::DEFAULT);
        self.return_site_funds(row);
        if let Some(id) = id {
            self.targets.clear_beacon(BeaconId::new(id));
        }
    }

    /// Write what a committed settings row says about a beacon's Mine
    /// settings: the settings it names, and nothing it is silent about.
    ///
    /// A written `seam_choice` is a change made on site to the target the
    /// beacon holds, so the held seam is released and the next decision tick
    /// chooses again under the new choice (`docs/design/targeting.md`, "Three
    /// reading rules", 2: a beacon keeps its target "until you change it on
    /// site").
    pub(crate) fn set_beacon_mine(&mut self, row: usize, edit: crate::mining::MineEdit) {
        let Some(settings) = self.beacons.mine_settings(row) else {
            return;
        };
        self.beacons
            .set_mine_settings(row, edit.applied_to(settings));
        if edit.seam_choice.is_some()
            && let Some(slot) = self.beacons.seams_mut().get_mut(row)
        {
            *slot = NO_FEATURE;
        }
    }

    /// Write a beacon's Quartermaster priority. The committed `set_priority`
    /// row, and the one player lever over power.
    pub(crate) fn set_beacon_priority(&mut self, row: usize, priority: u8) {
        if let Some(slot) = self.beacons.priorities_mut().get_mut(row) {
            *slot = priority;
        }
    }

    /// Write a Survey mandate's scout count. A committed settings row.
    pub(crate) fn set_beacon_scouts(&mut self, row: usize, scouts: u8) {
        if let Some(slot) = self.beacons.scout_counts_mut().get_mut(row) {
            *slot = scouts;
        }
    }

